import{_ as t,o,c as a,ae as n}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"OpenTofu","description":"","frontmatter":{"name":"OpenTofu","quadrant":"tools","history":[{"edition":"2026.2","ring":"adopt"}],"tags":["infrastructure","iac","licensing"]},"headers":[],"relativePath":"radar/items/opentofu.md","filePath":"radar/items/opentofu.md"}'),r={name:"radar/items/opentofu.md"};function s(i,e,d,f,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="opentofu" tabindex="-1">OpenTofu <a class="header-anchor" href="#opentofu" aria-label="Permalink to &quot;OpenTofu&quot;">​</a></h1><p>OpenTofu is the fork of <a href="./terraform.html">Terraform</a> taken at the last MPL 2.0 release, before HashiCorp&#39;s 2023 move to the Business Source License. Same HCL, same state model, same provider ecosystem; a module written for one reads for the other.</p><p>It sits in Adopt because the thing that made Terraform a safe default, an open license with no single company holding the terms, moved to OpenTofu and stayed there. The Linux Foundation governs it, MPL 2.0 covers every release with no four-year conversion clock, and no single vendor&#39;s acquisition or relicensing can change those terms unilaterally. That is the same bet the <a href="./sops.html">SOPS</a> and <a href="./mise.html">mise</a> placements are: a tool maintained under terms nobody can quietly revoke.</p><p>The fork has since earned Adopt on its own merits too, not just on the license it inherited. State encryption ships natively, without a wrapper script around <code>terraform.tfstate</code>. Provider and module authors iterate under a foundation instead of clearing changes with one company. Reaching for Terraform instead of OpenTofu needs a justification now, not the other way around.</p>',4)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
